  dailylife_21: {
    name: "Daily Life Set 21",
    color: "#553C9A",
    icon: "🏠",
    phrases: [
      { en: "She sang as well as danced", mr: "ಹಾಡುವುದರ ಜೊತೆಗೆ ನೃತ್ಯವನ್ನೂ ಮಾಡಿದ್ದಳು", roman: "Hāḍuvudara jòtègè nṛtyavannū māḍiddaḻu", hint: "" },
      { en: "He or me", mr: "ಅವನು ಅಥವಾ ನಾನು", roman: "Avanu athavā nānu", hint: "" },
      { en: "Do or die", mr: "ಮಾಡು ಇಲ್ಲವೇ ಮಡಿ", roman: "Māḍu illave maḍi", hint: "" },
      { en: "Neither he nor I were interested", mr: "ನನಗಾಗಲಿ ಅವನಿಗಾಗಲಿ ಆಸಕ್ತಿ ಇರಲಿಲ್ಲ", roman: "Nanagāgali avanigāgali āsakti iralilla", hint: "" },
      { en: "I finished study then I went to play", mr: "ಓದು ಮುಗಿಸಿ ಆಟವಾಡಲು ಹೋದೆ", roman: "Odu mugisi āṭavāḍalu hodè", hint: "" },
      { en: "I will call you then you enter on stage", mr: "ನಾನು ನಿಮ್ಮನ್ನು ಕರೆಯುತ್ತೇನೆ ನಂತರ ನೀವು ವೇದಿಕೆಯ ಮೇಲೆ ಪ್ರವೇಶಿಸಿ", roman: "Nānu nimmannu karèyuttenè naṃtara nīvu vedikèya melè praveśisi", hint: "" },
      { en: "As long as you want me, I will stay", mr: "ನೀನು ಎಲ್ಲಿಯವರೆಗೆ ನನ್ನನ್ನು ಬಯಸುತ್ತೀಯೋ ಅಲ್ಲಿಯವರೆಗೆ ನಾನು ಇರುತ್ತೇನೆ", roman: "Nīnu èlliyavarègè nannannu bayasuttīyo alliyavarègè nānu iruttenè", hint: "" },
      { en: "As long as you follow rules", mr: "ನೀವು ನಿಯಮಗಳನ್ನು ಅನುಸರಿಸುವವರೆಗೆ", roman: "Nīvu niyamagaḻannu anusarisuvavarègè", hint: "" },
      { en: "As far as I know, he is studious", mr: "ನನಗೆ ತಿಳಿದ ಮಟ್ಟಿಗೆ ಅವರು ಅಧ್ಯಯನಶೀಲರು", roman: "Nanagè tiḻida maṭṭigè avaru adhyayanaśīlaru", hint: "" },
      { en: "As far as India is concerned", mr: "ಭಾರತದ ಮಟ್ಟಿಗೆ", roman: "Bhāratada maṭṭigè", hint: "" },
      { en: "As far as literacy is concerned", mr: "ಸಾಕ್ಷರತೆಯ ಮಟ್ಟಿಗೆ", roman: "Sākṣaratèya maṭṭigè", hint: "" },
      { en: "He is blaming me as if I have not tried", mr: "ನಾನು ಪ್ರಯತ್ನಿಸಲಿಲ್ಲ ಎಂಬಂತೆ ಅವನು ನನ್ನ ಮೇಲೆ ಆರೋಪ ಮಾಡುತ್ತಿದ್ದಾನೆ", roman: "Nānu prayatnisalilla èṃbaṃtè avanu nanna melè āropa māḍuttiddānè", hint: "" },
      { en: "He passed by as if she was not there", mr: "ಅವಳಿಲ್ಲವೆಂಬಂತೆ ಅವನು ಹಾದುಹೋದನು", roman: "Avaḻillavèṃbaṃtè avanu hāduhodanu", hint: "" },
      { en: "As soon as he came", mr: "ಬಂದ ಕೂಡಲೇ", roman: "Baṃda kūḍale", hint: "" },
      { en: "As soon as she saw", mr: "ಅವಳು ನೋಡಿದ ತಕ್ಷಣ", roman: "Avaḻu noḍida takṣaṇa", hint: "" },
      { en: "As soon as they become", mr: "ಅವರು ಆದ ತಕ್ಷಣ", roman: "Avaru āda takṣaṇa", hint: "" },
      { en: "Let me know once he comes", mr: "ಅವರು ಬಂದರೆ ಒಮ್ಮೆ ತಿಳಿಸಿ", roman: "Avaru baṃdarè òmmè tiḻisi", hint: "" },
      { en: "Once I see your story I will give review", mr: "ನಿಮ್ಮ ಕಥೆಯನ್ನು ನೋಡಿದ ನಂತರ ನಾನು ವಿಮರ್ಶೆಯನ್ನು ನೀಡುತ್ತೇನೆ", roman: "Nimma kathèyannu noḍida naṃtara nānu vimarśèyannu nīḍuttenè", hint: "" },
      { en: "Rather than surrendering soldier will accept death", mr: "ಸೈನಿಕನು ಶರಣಾಗುವ ಬದಲು ಸಾವನ್ನು ಒಪ್ಪಿಕೊಳ್ಳುತ್ತಾನೆ", roman: "Sainikanu śaraṇāguva badalu sāvannu òppikòḻḻuttānè", hint: "" },
      { en: "I will take tea rather than coffee", mr: "ನಾನು ಕಾಫಿಗಿಂತ ಟೀ ತೆಗೆದುಕೊಳ್ಳುತ್ತೇನೆ", roman: "Nānu kāphigiṃta ṭī tègèdukòḻḻuttenè", hint: "" },
      { en: "I will work hard so that I will win", mr: "ನಾನು ಗೆಲ್ಲಲು ಶ್ರಮಿಸುತ್ತೇನೆ", roman: "Nānu gèllalu śramisuttenè", hint: "" },
      { en: "We should avoid plastic so that less pollution", mr: "ಮಾಲಿನ್ಯವನ್ನು ಕಡಿಮೆ ಮಾಡಲು ನಾವು ಪ್ಲಾಸ್ಟಿಕ್ ಅನ್ನು ತ್ಯಜಿಸಬೇಕು", roman: "Mālinyavannu kaḍimè māḍalu nāvu plāsṭik annu tyajisabeku", hint: "" },
      { en: "He cheated me whereas I was helping him", mr: "ನಾನು ಅವನಿಗೆ ಸಹಾಯ ಮಾಡುತ್ತಿದ್ದಾಗ ಅವನು ನನಗೆ ಮೋಸ ಮಾಡಿದನು", roman: "Nānu avanigè sahāya māḍuttiddāga avanu nanagè mosa māḍidanu", hint: "" },
      { en: "Govt said prices declined whereas inflation rose", mr: "ಬೆಲೆ ಇಳಿಕೆ ಆದರೆ ಹಣದುಬ್ಬರ ಏರಿಕೆಯಾಗಿದೆ ಎಂದು ಸರ್ಕಾರ ಹೇಳಿದೆ", roman: "Bèlè iḻikè ādarè haṇadubbara erikèyāgidè èṃdu sarkāra heḻidè", hint: "" },
      { en: "I did not know whether he is going", mr: "ಅವನು ಹೋಗುತ್ತಿದ್ದಾನೆಯೇ ಎಂದು ನನಗೆ ತಿಳಿದಿರಲಿಲ್ಲ", roman: "Avanu hoguttiddānèye èṃdu nanagè tiḻidiralilla", hint: "" },
      { en: "She could not realize whether to speak or not", mr: "ಮಾತನಾಡಬೇಕೋ ಬೇಡವೋ ಎಂದು ಅವಳಿಗೆ ಅರಿವಾಗಲಿಲ್ಲ", roman: "Mātanāḍabeko beḍavo èṃdu avaḻigè arivāgalilla", hint: "" },
      { en: "Do this otherwise you will not win", mr: "ಇದನ್ನು ಮಾಡಿ ಇಲ್ಲದಿದ್ದರೆ ನೀವು ಗೆಲ್ಲುವುದಿಲ್ಲ", roman: "Idannu māḍi illadiddarè nīvu gèlluvudilla", hint: "" },
      { en: "He should inform me otherwise I will not know", mr: "ಅವನು ನನಗೆ ತಿಳಿಸಬೇಕು ಇಲ್ಲದಿದ್ದರೆ ನನಗೆ ಗೊತ್ತಿಲ್ಲ", roman: "Avanu nanagè tiḻisabeku illadiddarè nanagè gòttilla", hint: "" },
      { en: "I also ran", mr: "ನಾನೂ ಓಡಿದೆ", roman: "Nānū oḍidè", hint: "" },
      { en: "He will come tomorrow as well", mr: "ನಾಳೆಯೂ ಬರುತ್ತಾನೆ", roman: "Nāḻèyū baruttānè", hint: "" }
    ]
  },
